def message(value):
    text = str(value)
    if os.environ.get('HUE2LOX_INSTALL_LANG') != 'de':
        return text
    # Longest phrases first; only documented CLI text is translated, never paths/values.
    for english, german in sorted(DE.items(), key=lambda item: -len(item[0])):
        text = text.replace(english, german)
    return text


def localized_print(*args, **kwargs):
    builtins.print(*(message(arg) if isinstance(arg, str) else arg for arg in args), **kwargs)
